/**
 * Ögonlocksjournal — schema-driven from Meridiq 16388 (G4).
 * Registry: journal-bleph-schemas.js (generated by buildJournalSchemas.py)
 */
(() => {
  'use strict';

  const MULTI_FIELD_KEYS = new Set();
  const TRISTATE_FIELD_KEYS = new Set();
  const DATE_FIELD_KEYS = new Set(['dagens_datum']);

  function escapeHtml(value) {
    return String(value ?? '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function asArray(value) {
    return Array.isArray(value) ? value : [];
  }

  function chipHtml(label, tone) {
    return `<span class="focus-customer-chip focus-customer-chip--${tone}">${escapeHtml(label)}</span>`;
  }

  function tristateOptions(selected) {
    const current = selected === true ? 'true' : selected === false ? 'false' : '';
    return `
      <option value=""${current === '' ? ' selected' : ''}>—</option>
      <option value="true"${current === 'true' ? ' selected' : ''}>Ja</option>
      <option value="false"${current === 'false' ? ' selected' : ''}>Nej</option>
    `;
  }

  function registerField(field) {
    if (field.type === 'checkboxes') MULTI_FIELD_KEYS.add(field.key);
    if (field.type === 'tristate' || field.type === 'yes_no_textbox') {
      TRISTATE_FIELD_KEYS.add(field.key);
    }
    if (DATE_FIELD_KEYS.has(field.key)) field.type = 'date';
    if (field.meridiqType === 'textbox' && field.type === 'text') field.type = 'textarea';
  }

  function renderField(field, fields = {}) {
    const key = field.key;
    const value = fields[key];
    const disabled = field.disabled ? ' disabled' : '';
    const id = `bleph-field-${key}`;

    if (field.type === 'yes_no_textbox') {
      const textKey = field.textKey || `${key}Text`;
      return `
        <div class="patient-master-tp-field patient-master-tp-field--split">
          <label class="patient-master-tp-field" for="${id}">
            <span class="patient-master-muted">${escapeHtml(field.label)}</span>
            <select id="${id}" name="${escapeHtml(key)}" data-bleph-field="${escapeHtml(key)}"${disabled}>
              ${tristateOptions(value)}
            </select>
          </label>
          <label class="patient-master-tp-field" for="${id}-text">
            <span class="patient-master-muted">Kompletterande text</span>
            <input id="${id}-text" type="text" name="${escapeHtml(textKey)}" data-bleph-field="${escapeHtml(textKey)}" value="${escapeHtml(fields[textKey] || '')}"${disabled} />
          </label>
        </div>
      `;
    }

    if (field.type === 'tristate') {
      return `
        <label class="patient-master-tp-field" for="${id}">
          <span class="patient-master-muted">${escapeHtml(field.label)}</span>
          <select id="${id}" name="${escapeHtml(key)}" data-bleph-field="${escapeHtml(key)}"${disabled}>
            ${tristateOptions(value)}
          </select>
        </label>
      `;
    }

    if (field.type === 'textarea') {
      return `
        <label class="patient-master-tp-field" for="${id}">
          <span class="patient-master-muted">${escapeHtml(field.label)}</span>
          <textarea id="${id}" name="${escapeHtml(key)}" data-bleph-field="${escapeHtml(key)}" rows="3"${disabled}>${escapeHtml(value || '')}</textarea>
        </label>
      `;
    }

    return `
      <label class="patient-master-tp-field" for="${id}">
        <span class="patient-master-muted">${escapeHtml(field.label)}</span>
        <input id="${id}" type="${field.type === 'date' ? 'date' : 'text'}" name="${escapeHtml(key)}" data-bleph-field="${escapeHtml(key)}" value="${escapeHtml(value || '')}"${disabled} />
      </label>
    `;
  }

  function render(config, entry, options = {}) {
    const fields = entry?.fields && typeof entry.fields === 'object' ? entry.fields : {};
    const locked = Boolean(options.locked || entry?.locked);
    const entryId = String(entry?.entryId || '');
    const title = String(entry?.title || config.title || 'Ögonlocksjournal');
    const sections = asArray(config.sections);

    const sectionsHtml = sections
      .map(
        (section) => `
      <details class="patient-master-tp-section" open>
        <summary>${escapeHtml(section.title)}</summary>
        <div class="patient-master-tp-section-body">
          ${section.fields.map((field) => renderField({ ...field, disabled: locked }, fields)).join('')}
        </div>
      </details>`
      )
      .join('');

    return `
      <article class="focus-customer-data-card patient-master-tp-card${locked ? ' is-locked' : ''}" data-bleph-journal-form data-bleph-entry-id="${escapeHtml(entryId)}">
        <header class="patient-master-tp-header">
          <div>
            <h4>${escapeHtml(title)}</h4>
            <p class="patient-master-muted">${locked ? 'Signerad och låst.' : config.subtitle}</p>
          </div>
          ${
            locked
              ? chipHtml('Låst', 'violet')
              : `<button type="submit" class="customers-utility-button patient-master-tp-save">Spara journal</button>`
          }
        </header>
        ${sectionsHtml}
      </article>
    `;
  }

  function readForm(root) {
    if (!root) return {};
    const next = {};
    MULTI_FIELD_KEYS.forEach((key) => {
      next[key] = [];
    });
    root.querySelectorAll('[data-bleph-field]').forEach((el) => {
      const key = el.dataset.blephField;
      if (!key) return;
      if (el.dataset.blephMulti === 'true') {
        if (el.checked) next[key].push(el.value);
        return;
      }
      if (el.tagName === 'SELECT') {
        const raw = String(el.value || '');
        if (TRISTATE_FIELD_KEYS.has(key)) {
          if (raw === 'true') next[key] = true;
          else if (raw === 'false') next[key] = false;
          else next[key] = null;
          return;
        }
        next[key] = raw;
        return;
      }
      next[key] = String(el.value || '').trim();
    });
    return next;
  }

  const schema = window.ArcanaJournalBlephSchemaRegistry?.curatiio_bleph;
  const sections = asArray(schema?.sections).map((section) => ({
    title: section.title,
    fields: asArray(section.fields).map((field) => ({ ...field })),
  }));
  sections.forEach((section) => section.fields.forEach(registerField));

  const config = Object.freeze({
    formVariant: 'curatiio_bleph',
    meridiqQuestionaryId: schema?.meridiqQuestionaryId || 16388,
    title: schema?.title || 'Journal | Ögonlocksplastik',
    subtitle: schema?.subtitle || 'Meridiq mall 16388 · Fyll i efter behandling — sparas på denna kund.',
    sections,
    emptyDefaults: { ...(schema?.emptyDefaults || {}) },
  });

  window.ArcanaJournalBlephForm = Object.freeze({
    render: (entry, options) => render(config, entry, options),
    readForm,
    SECTIONS: sections,
    config,
    defaultFields(patient = {}) {
      const base = { ...config.emptyDefaults };
      const name = String(patient.displayName || '').trim();
      const parts = name.split(/\s+/);
      base.fornamn = parts[0] || base.fornamn || '';
      base.efternamn = parts.slice(1).join(' ') || base.efternamn || '';
      base.personnummer = patient.personnummer || base.personnummer || '';
      base.dagens_datum = new Date().toISOString().slice(0, 10);
      return base;
    },
  });
})();
